import { HistoricalDocument } from '../../types';

export const codigoManuCapitulo4: HistoricalDocument = {
  id: 'codigo-manu-capitulo-4',
  title: 'Capítulo IV',
  subtitle: 'Dos Meios de Subsistência e dos Deveres do Brâmane',
  date: 'c. 200 a.C. – 200 d.C.',
  era: 'Índia Antiga',
  language: 'Sânscrito',
  description: 'Define as fontes lícitas de subsistência do brâmane e as regras de conduta cotidiana e pureza ritual.',
  parentCollectionId: 'codigo-de-manu',
  sections: [
    {
      id: 'versos',
      title: 'Capítulo IV',
      type: 'articles',
      articles: [
        { id: 'cm-4-1', number: 'Verso 1', text: `Tendo habitado com um professor durante a quarta parte da (vida de um) homem, um *Brahmana* deverá viver durante o segundo quarto (de sua existência) em sua casa, após ter desposado uma esposa.` },
        { id: 'cm-4-2', number: 'Verso 2', text: `Um *Brahmana* deve buscar um meio de subsistência que não cause nenhuma, ou ao menos pouca dor (aos outros), e viver (disso) exceto em tempos de aflição.` },
        { id: 'cm-4-3', number: 'Verso 3', text: `Com o propósito de ganhar a mera subsistência, que ele acumule propriedade por (seguir aquelas) ocupações irrepreensíveis (que são prescritas para) sua (casta), sem fatigar (indevidamente) seu corpo.` },
        { id: 'cm-4-4', number: 'Verso 4', text: `Ele pode subsistir por *Rita* (verdade), e *Amrita* (ambrosia), ou por *Mrita* (morte) e por *Pramrita* (o que causa muitas mortes); ou mesmo pela (modalidade) chamada *Satyanrita* (uma mistura de verdade e falsidade), mas nunca por *Svavritti* (o modo de vida de um cão).` },
        { id: 'cm-4-5', number: 'Verso 5', text: `Por *Rita* entender-se-á a respiga de milho; por *Amrita*, o que é dado sem ser pedido; por *Mrita*, o alimento obtido pela mendicância e a agricultura é declarada ser *Pramrita*.` },
        { id: 'cm-4-6', number: 'Verso 6', text: `Mas o comércio e (o empréstimo de dinheiro) são *Satyanrita*, até mesmo disso alguém pode subsistir. O serviço é chamado *Svavritti*; portanto deve-se evitá-lo.` },
        { id: 'cm-4-7', number: 'Verso 7', text: `Ele pode ou possuir o suficiente para encher um celeiro, ou um estoque que encha uma jarra de grãos; ou ele pode coletar o que é suficiente para três dias, ou não fazer nenhuma provisão para o dia seguinte.` },
        { id: 'cm-4-8', number: 'Verso 8', text: `Ademais, entre estes quatro chefes de família *Brahmanas*, cada um nomeado mais tarde deve ser considerado mais distinto, e através de sua virtude ter conquistado o mundo mais completamente.` },
        { id: 'cm-4-9', number: 'Verso 9', text: `Um destes segue seis ocupações, outro subsiste de três, um de duas, mas o quarto vive pelo *Brahmasattra*.` },
        { id: 'cm-4-10', number: 'Verso 10', text: `Aquele que se mantém recolhendo grãos e espigas de milho, deve estar sempre focado na (realização do) *Agnihotra*, e constantemente oferecer apenas aqueles *Ishtis*, que são prescritos para os dias da conjunção e oposição (da lua), e para os solstícios.` },
        { id: 'cm-4-11', number: 'Verso 11', text: `Que ele nunca, em prol da subsistência, siga os caminhos do mundo; que ele viva a vida pura, reta, e honesta de um *Brahmana*.` },
        { id: 'cm-4-12', number: 'Verso 12', text: `Aquele que deseja a felicidade deve esforçar-se por uma disposição perfeitamente contente e controlar a si mesmo; pois a felicidade tem o contentamento por sua raiz, a raiz da infelicidade é a (disposição) contrária.` },
        { id: 'cm-4-13', number: 'Verso 13', text: `Um *Brahmana*, que é um *Snataka* e subsiste por um dos modos de vida (mencionados acima), deve cumprir os (seguintes) deveres que garantem a bem-aventurança celestial, vida longa, e fama.` },
        { id: 'cm-4-14', number: 'Verso 14', text: `Que ele, incansável, realize diariamente os ritos prescritos para ele no Veda; pois aquele que os realiza de acordo com sua capacidade, alcança o estado mais alto.` },
        { id: 'cm-4-15', number: 'Verso 15', text: `Quer ele seja rico ou mesmo em aflição, que ele não busque riqueza através de buscas às quais os homens se apegam, nem por ocupações proibidas, nem (que ele aceite presentes) de qualquer (doador, seja ele quem for).` },
        { id: 'cm-4-16', number: 'Verso 16', text: `Que ele não, por desejo (de gozos), apegue-se a quaisquer prazeres sensuais, e que ele cuidadosamente evite um apego excessivo a eles, por (refletir sobre sua falta de valor em) seu coração.` },
        { id: 'cm-4-17', number: 'Verso 17', text: `Que ele evite todos os (meios de adquirir) riqueza que impeçam o estudo do Veda; (que ele se mantenha) de qualquer forma, mas estude, porque essa (devoção ao estudo do Veda garante) a realização de seus objetivos.` },
        { id: 'cm-4-18', number: 'Verso 18', text: `Que ele caminhe aqui (na terra), trazendo sua veste, fala, e pensamentos a uma conformidade com sua idade, sua ocupação, sua riqueza, seu aprendizado sagrado, e sua raça.` },
        { id: 'cm-4-19', number: 'Verso 19', text: `Que ele diariamente se debruce sobre aqueles Institutos da ciência que logo dão aumento de sabedoria, aqueles que ensinam a aquisição de riqueza, aqueles que são benéficos (para outras questões mundanas), e igualmente sobre os *Nigamas* que explicam o Veda.` },
        { id: 'cm-4-20', number: 'Verso 20', text: `Pois quanto mais um homem estuda completamente os Institutos da ciência, mais ele os compreende plenamente, e seu grande aprendizado brilha esplendidamente.` },
        { id: 'cm-4-21', number: 'Verso 21', text: `Que ele nunca, se for capaz (de realizá-los), negligencie os sacrifícios aos sábios, aos deuses, aos *Bhutas*, aos homens, e aos manes.` },
        { id: 'cm-4-22', number: 'Verso 22', text: `Alguns homens que conhecem as ordenanças para os ritos sacrificiais, sempre oferecem esses grandes sacrifícios em seus órgãos (de sensação), sem nenhum esforço (externo).` },
        { id: 'cm-4-23', number: 'Verso 23', text: `Sabendo que a (realização do) sacrifício em sua fala e sua respiração rende (recompensas) imperecíveis, alguns sempre oferecem sua respiração em sua fala, e sua fala em sua respiração.` },
        { id: 'cm-4-24', number: 'Verso 24', text: `Outros *Brahmanas*, vendo com o olho do conhecimento que a realização desses ritos tem o conhecimento por sua raiz, sempre os realizam através do conhecimento apenas.` },
        { id: 'cm-4-25', number: 'Verso 25', text: `Um *Brahmana* deverá sempre oferecer o *Agnihotra* no princípio ou no fim do dia e da noite, e os (*Ishtis*) *Darsa* e *Paurnamasa* no final de cada quinzena,` },
        { id: 'cm-4-26', number: 'Verso 26', text: `Quando o grão velho tiver sido consumido o *Ishti* (*Agrayana*) com o grão novo, no final das (três) estações os sacrifícios (*Katurmasya*), nos solstícios um (sacrifício) animal, no final do ano oferendas de *Soma*.` },
        { id: 'cm-4-27', number: 'Verso 27', text: `Um *Brahmana*, que mantém fogos sagrados, deverá, se ele deseja viver muito, não comer grão novo ou carne, sem ter oferecido o *Ishti* (*Agrayana*) com grão novo e um (sacrifício) animal.` },
        { id: 'cm-4-28', number: 'Verso 28', text: `Pois os seus fogos, não sendo adorados por oferendas de grão novo e de um animal, buscam devorar seus espíritos vitais, (porque eles são) ávidos por grão novo e carne.` },
        { id: 'cm-4-29', number: 'Verso 29', text: `Nenhum convidado deve ficar em sua casa sem ser honrado, de acordo com sua capacidade, com um assento, comida, um sofá, água, ou raízes e frutas.` },
        { id: 'cm-4-30', number: 'Verso 30', text: `Que ele não honre, nem com um cumprimento, os hereges, os homens que seguem ocupações proibidas, os homens que vivem como gatos, os trapaceiros, os lógicos, (argumentando contra o Veda), e aqueles que vivem como garças.` },
        { id: 'cm-4-31', number: 'Verso 31', text: `Aqueles que se tornaram *Snatakas* após estudar o Veda, ou após completar seus votos, (e) chefes de família, que são *Srotriyas*, deve-se adorar por (presentes de comida) sagrados aos deuses e manes, mas deve-se evitar aqueles que são diferentes.` },
        { id: 'cm-4-32', number: 'Verso 32', text: `Um chefe de família deve dar (tanta comida) quanto ele seja capaz (de poupar) àqueles que não cozinham para si mesmos, e a todos os seres deve-se distribuir (comida) sem detrimento (ao próprio interesse).` },
        { id: 'cm-4-33', number: 'Verso 33', text: `Um *Snataka* que definha de fome, pode mendigar riqueza de um rei, de um para quem ele sacrifica, e de um pupilo, mas não de outros; essa é uma regra estabelecida.` },
        { id: 'cm-4-34', number: 'Verso 34', text: `Um *Snataka* que é capaz (de obter alimento) nunca deverá se desgastar com a fome, nem deverá usar roupas velhas ou sujas, se ele possuir propriedade.` },
        { id: 'cm-4-35', number: 'Verso 35', text: `Mantendo seu cabelo, unhas, e barba cortados, subjugando suas paixões por austeridades, usando vestes brancas e (mantendo-se) puro, ele deverá estar sempre engajado no estudo do Veda e (tais atos que são) conducentes ao seu bem-estar.` },
        { id: 'cm-4-36', number: 'Verso 36', text: `Ele deverá carregar um cajado de bambu, um pote cheio de água, um cordão sagrado, um feixe de grama *Kusa*, e (usar) dois brilhantes brincos de ouro.` },
        { id: 'cm-4-37', number: 'Verso 37', text: `Que ele nunca olhe para o sol, quando ele se põe ou nasce, é eclipsado ou refletido na água, ou está no meio do céu.` },
        { id: 'cm-4-38', number: 'Verso 38', text: `Que ele não pise sobre uma corda à qual um bezerro está amarrado, que ele não corra quando chover, e que ele não olhe para sua própria imagem na água; essa é uma regra estabelecida.` },
        { id: 'cm-4-39', number: 'Verso 39', text: `Que ele passe por (um monte de) terra, uma vaca, um ídolo, um *Brahmana*, manteiga clarificada, mel, um cruzamento, e árvores bem conhecidas, virando sua mão direita em direção a eles.` },
        { id: 'cm-4-40', number: 'Verso 40', text: `Que ele, embora louco de desejo, não se aproxime de sua esposa quando suas regras (*menstruação*) aparecerem; nem que ele durma com ela na mesma cama.` },
        { id: 'cm-4-41', number: 'Verso 41', text: `Pois a sabedoria, a energia, a força, a visão, e a vitalidade de um homem que se aproxima de uma mulher coberta com excreções menstruais, perecem totalmente.` },
        { id: 'cm-4-42', number: 'Verso 42', text: `Se ele a evita, enquanto ela está nessa condição, sua sabedoria, energia, força, visão, e vitalidade aumentarão.` },
        { id: 'cm-4-43', number: 'Verso 43', text: `Que ele não coma na companhia de sua esposa, nem olhe para ela, enquanto ela come, espirra, boceja, ou senta-se à vontade.` },
        { id: 'cm-4-44', number: 'Verso 44', text: `Um *Brahmana* que deseja energia não deve olhar para (uma mulher) que aplica colírio aos seus olhos, se ungiu ou descobriu, ou dá à luz (uma criança).` },
        { id: 'cm-4-45', number: 'Verso 45', text: `Que ele não coma, vestido com apenas uma veste; que ele não se banhe nu; que ele não excrete urina em uma estrada, em cinzas, ou num curral,` },
        { id: 'cm-4-46', number: 'Verso 46', text: `Nem em terra arada, na água, em um altar de tijolos, em uma montanha, nas ruínas de um templo, nem nunca em um formigueiro,` },
        { id: 'cm-4-47', number: 'Verso 47', text: `Nem em buracos habitados por criaturas vivas, nem enquanto ele caminha ou fica de pé, nem ao alcançar a margem de um rio, nem no topo de uma montanha.` },
        { id: 'cm-4-48', number: 'Verso 48', text: `Que ele nunca excrete fezes ou urina, de frente para o vento, ou um fogo, ou olhando em direção a um *Brahmana*, ao sol, à água, ou vacas.` },
        { id: 'cm-4-49', number: 'Verso 49', text: `Ele pode aliviar a si mesmo, tendo coberto (o chão) com gravetos, torrões, folhas, grama, e semelhantes, refreando sua fala, (mantendo-se) puro, embrulhando seu corpo, e cobrindo sua cabeça.` },
        { id: 'cm-4-50', number: 'Verso 50', text: `Que ele excrete fezes e urina, no dia virando-se para o norte, à noite virando-se para o sul, durante os dois crepúsculos na mesma (posição) que de dia.` },
        { id: 'cm-4-51', number: 'Verso 51', text: `Na sombra ou na escuridão um *Brahmana* pode, tanto de dia quanto à noite, fazê-lo, assumindo qualquer posição que lhe aprouver; igualmente quando sua vida estiver em perigo.` },
        { id: 'cm-4-52', number: 'Verso 52', text: `O intelecto de (um homem) que excrete urina contra um fogo, o sol, a lua, na água, contra um *Brahmana*, uma vaca, ou o vento, perece.` },
        { id: 'cm-4-53', number: 'Verso 53', text: `Que ele não sopre um fogo com sua boca; que ele não olhe para uma mulher nua; que ele não jogue nenhuma substância impura no fogo, e que ele não aqueça seus pés nele.` },
        { id: 'cm-4-54', number: 'Verso 54', text: `Que ele não coloque (o fogo) debaixo de (uma cama ou algo semelhante); nem pise sobre ele, nem o coloque (quando dormir) no (fim do) pé (de sua cama); que ele não atormente criaturas vivas.` },
        { id: 'cm-4-55', number: 'Verso 55', text: `Que ele não coma, nem viaje, nem durma durante o crepúsculo; que ele não arranhe o chão; que ele não tire a sua guirlanda.` },
        { id: 'cm-4-56', number: 'Verso 56', text: `Que ele não jogue urina ou fezes na água, nem saliva, nem (roupas) manchadas por substâncias impuras, nem qualquer outra (impureza), nem sangue, nem coisas venenosas.` },
        { id: 'cm-4-57', number: 'Verso 57', text: `Que ele não durma sozinho em uma habitação deserta; que ele não acorde (um superior) que está dormindo; que ele não converse com uma mulher menstruada; nem que ele vá a um sacrifício, se ele não for escolhido (para ser o sacerdote oficiante).` },
        { id: 'cm-4-58', number: 'Verso 58', text: `Que ele mantenha seu braço direito descoberto em um lugar onde um fogo sagrado é mantido, num curral, na presença de *Brahmanas*, durante a recitação particular do Veda, e nas refeições.` },
        { id: 'cm-4-59', number: 'Verso 59', text: `Que ele não interrompa uma vaca que está amamentando (seu bezerro), nem conte a ninguém sobre isso. Um homem sábio, se ele vir um arco-íris no céu, não deve apontá-lo para ninguém.` },
        { id: 'cm-4-60', number: 'Verso 60', text: `Que ele não habite em uma vila onde a lei sagrada não é obedecida, nem (fique) muito tempo onde doenças são endêmicas; que ele não vá sozinho em uma jornada, nem resida muito tempo em uma montanha.` },
        { id: 'cm-4-61', number: 'Verso 61', text: `Que ele não habite em um país onde os governantes são *Sudras*, nem num que seja cercado por homens injustos, nem num que tenha se tornado sujeito a hereges, nem num apinhado de homens das castas mais baixas.` },
        { id: 'cm-4-62', number: 'Verso 62', text: `Que ele não coma nada de onde o óleo tenha sido extraído; que ele não seja um glutão; que ele não coma muito cedo (pela manhã), nem muito tarde (à noite), nem (tome nenhum alimento) à noite, se ele comeu (até fartar-se) pela manhã.` },
        { id: 'cm-4-63', number: 'Verso 63', text: `Que ele não se esforce sem um propósito; que ele não beba água de suas palmas unidas; que ele não coma alimento (colocado) em seu colo; que ele não demonstre curiosidade (ociosa).` },
        { id: 'cm-4-64', number: 'Verso 64', text: `Que ele não dance, nem cante, nem toque instrumentos musicais, nem bata (em seus membros), nem ranja seus dentes, nem que ele faça ruídos bizarros, mesmo que esteja apaixonado (ou enfurecido).` },
        { id: 'cm-4-65', number: 'Verso 65', text: `Que ele nunca lave seus pés em um vaso de latão branco; que ele não coma de um prato (de barro) quebrado, nem de um que (a julgar) por sua aparência (seja) imundo.` },
        { id: 'cm-4-66', number: 'Verso 66', text: `Que ele não use sapatos, roupas, um cordão sagrado, ornamentos, uma guirlanda, ou um vaso de água que tenham sido usados por outros.` },
        { id: 'cm-4-67', number: 'Verso 67', text: `Que ele não viaje com bestas de carga não treinadas, nem com (animais) que são atormentados por fome ou doença, ou cujos chifres, olhos, e cascos foram feridos, ou cujas caudas foram desfiguradas.` },
        { id: 'cm-4-68', number: 'Verso 68', text: `Que ele viaje sempre com (bestas) que estão bem domadas, velozes, dotadas de marcas de sorte, e perfeitas em cor e forma, sem instigá-las muito com o aguilhão.` },
        { id: 'cm-4-69', number: 'Verso 69', text: `O sol da manhã, a fumaça subindo de um cadáver (em chamas), e um assento quebrado devem ser evitados. Que ele não corte suas unhas ou cabelo, e não arranque suas unhas com seus dentes.` },
        { id: 'cm-4-70', number: 'Verso 70', text: `Que ele não esmague terra ou torrões, nem arranque grama com suas unhas; que ele não faça nada que seja inútil ou terá resultados desagradáveis no futuro.` },
        { id: 'cm-4-71', number: 'Verso 71', text: `Um homem que esmaga torrões, arranca grama, ou morde suas unhas, vai logo à perdição, igualmente um informante e aquele que negligencia (as regras de) purificação.` },
        { id: 'cm-4-72', number: 'Verso 72', text: `Que ele não brigue; que ele não use uma guirlanda sobre (seu cabelo). Montar nas costas de vacas (ou de bois) é de qualquer forma um ato censurável.` },
        { id: 'cm-4-73', number: 'Verso 73', text: `Que ele não entre em uma vila ou casa murada exceto pelo portão, e à noite que ele se mantenha a uma longa distância das raízes das árvores.` },
        { id: 'cm-4-74', number: 'Verso 74', text: `Que ele nunca brinque com dados, nem tire ele mesmo seus sapatos; que ele não coma, deitado numa cama, nem o que lhe foi colocado em sua mão ou num assento.` },
        { id: 'cm-4-75', number: 'Verso 75', text: `Que ele não coma após o pôr do sol qualquer (alimento) contendo grãos de gergelim; que ele nunca durma nu, nem vá a lugar nenhum não purificado (após as refeições).` },
        { id: 'cm-4-76', number: 'Verso 76', text: `Que ele coma enquanto seus pés estiverem (ainda) molhados (da ablução), mas que ele não vá para a cama com os pés molhados. Aquele que come enquanto seus pés estiverem (ainda) molhados, alcançará longa vida.` },
        { id: 'cm-4-77', number: 'Verso 77', text: `Que ele nunca entre em um lugar, difícil de acesso, que é impenetrável ao seu olho; que ele não olhe para urina ou excremento, nem cruze um rio (nadando) com seus braços.` },
        { id: 'cm-4-78', number: 'Verso 78', text: `Que ele não pise em cabelos, cinzas, ossos, cacos de cerâmica, sementes de algodão ou palha, se ele desejar longa vida.` },
        { id: 'cm-4-79', number: 'Verso 79', text: `Que ele não fique junto com párias, nem com *Kandalas*, nem com *Pukkasas*, nem com tolos, nem com homens arrogantes, nem com homens de casta baixa, nem com *Antyavasayins*.` },
        { id: 'cm-4-80', number: 'Verso 80', text: `Que ele não dê a um *Sudra* conselhos, nem os restos (de sua refeição), nem alimento oferecido aos deuses; nem que ele explique a lei sagrada (a tal homem), nem imponha (a ele) uma penitência.` },
        { id: 'cm-4-81', number: 'Verso 81', text: `Pois aquele que explica a lei sagrada (a um *Sudra*) ou dita a ele uma penitência, afundará junto com esse (homem) no inferno (chamado) *Asamvrita*.` },
        { id: 'cm-4-82', number: 'Verso 82', text: `Que ele não coce sua cabeça com ambas as mãos unidas; que ele não a toque enquanto estiver impuro, nem se banhe sem (submergi-)la.` },
        { id: 'cm-4-83', number: 'Verso 83', text: `Que ele evite (com raiva) agarrar (o próprio cabelo ou de outros homens), ou golpear (a si mesmo ou aos outros) na cabeça. Quando ele se banhar (submergindo) sua cabeça, ele não deverá tocar nenhum de seus membros com óleo.` },
        { id: 'cm-4-84', number: 'Verso 84', text: `Que ele não aceite presentes de um rei que não descende da raça *Kshatriya*, nem de açougueiros, fabricantes de óleo, e taberneiros, nem daqueles que subsistem do ganho de prostitutas.` },
        { id: 'cm-4-85', number: 'Verso 85', text: `Um lagar de óleo é tão (ruim) quanto dez matadouros, uma taverna tão (ruim quanto) dez lagares de óleo, um bordel tão (ruim quanto) dez tavernas, um rei tão (ruim quanto) dez bordeis.` },
        { id: 'cm-4-86', number: 'Verso 86', text: `Um rei é declarado ser igual (em maldade) a um açougueiro que mantém cem mil matadouros; aceitar presentes dele é um (crime) terrível.` },
        { id: 'cm-4-87', number: 'Verso 87', text: `Aquele que aceita presentes de um rei avarento que age de maneira contrária aos Institutos (da lei sagrada), irá em sucessão aos vinte e um infernos seguintes:` },
        { id: 'cm-4-88', number: 'Verso 88', text: `*Tamisra*, *Andhatamisra*, *Maharaurava*, *Raurava*, o inferno *Kalasutra*, *Mahanaraka*,` },
        { id: 'cm-4-89', number: 'Verso 89', text: `*Samgivana*, *Mahaviki*, *Tapana*, *Sampratapana*, *Samghata*, *Sakakola*, *Kudmala*, *Putimrittika*,` },
        { id: 'cm-4-90', number: 'Verso 90', text: `*Lohasanku*, *Rigisha*, *Pathin*, o rio (flamejante), *Salmala*, *Asipatravana*, e *Lohakaraka*.` },
        { id: 'cm-4-91', number: 'Verso 91', text: `*Brahmanas* eruditos, que sabem disso, que estudam o Veda e desejam bem-aventurança após a morte, não aceitam presentes de um rei.` },
        { id: 'cm-4-92', number: 'Verso 92', text: `Que ele acorde no *muhurta*, sagrado para Brahman, e pense (na aquisição do) mérito espiritual e riqueza, na fadiga corporal decorrente disso, e no verdadeiro significado do Veda.` },
        { id: 'cm-4-93', number: 'Verso 93', text: `Quando ele tiver se levantado, tiver aliviado as necessidades da natureza e purificado a si mesmo cuidadosamente, que ele fique de pé durante o crepúsculo matutino, murmurando por muito tempo (a *Gayatri*), e no tempo adequado (ele deve realizar de maneira semelhante) a (devoção) do entardecer.` },
        { id: 'cm-4-94', number: 'Verso 94', text: `Ao prolongar as devoções do crepúsculo, os sábios obtiveram vida longa, sabedoria, honra, fama, e excelência no conhecimento Védico.` },
        { id: 'cm-4-95', number: 'Verso 95', text: `Tendo realizado o *Upakarman* de acordo com a regra prescrita (na lua cheia do mês) *Sravana*, ou na de *Praushthapada* (*Bhadrapada*), um *Brahmana* deverá estudar diligentemente os Vedas durante quatro meses e meio.` },
        { id: 'cm-4-96', number: 'Verso 96', text: `Quando o dia de *Pushya* (do mês *Pausha*), ou o primeiro dia da metade clara de *Magha* tiver chegado, um *Brahmana* deverá realizar pela manhã o *Utsargana* dos Vedas.` },
        { id: 'cm-4-97', number: 'Verso 97', text: `Tendo realizado o *Utsarga* fora (da vila), como os Institutos (da lei sagrada) prescrevem, ele deverá parar de ler durante dois dias e a noite interveniente, ou durante aquele dia (do *Utsarga*) e a noite (seguinte).` },
        { id: 'cm-4-98', number: 'Verso 98', text: `Posteriormente ele deverá recitar diligentemente os Vedas durante as (metades) claras (dos meses), e estudar devidamente todos os *Angas* dos Vedas durante as quinzenas escuras.` },
        { id: 'cm-4-99', number: 'Verso 99', text: `Que ele não recite (os textos) de forma indistinta, nem na presença de *Sudras*; nem que ele, se na última parte da noite ele estiver cansado de recitar o Veda, volte a dormir.` },
        { id: 'cm-4-100', number: 'Verso 100', text: `De acordo com a regra declarada acima, que ele recite a (porção) diária (dos) *Mantras*, e um *Brahmana* zeloso, (que não está) em aflição, (deverá estudar) o *Brahmana* e o *Mantrasamhita*.` },
        { id: 'cm-4-101', number: 'Verso 101', text: `Que aquele que estuda sempre evite (ler) nas seguintes ocasiões quando o estudo do Veda é proibido, e (que) aquele que ensina os pupilos de acordo com a regra prescrita (faça-o igualmente).` },
        { id: 'cm-4-102', number: 'Verso 102', text: `Aqueles que conhecem as (regras de) recitação declaram que na estação chuvosa o estudo do Veda deve ser parado nestas duas (ocasiões), quando o vento é audível à noite, e quando levanta a poeira durante o dia.` },
        { id: 'cm-4-103', number: 'Verso 103', text: `Manu afirmou que quando relâmpago, trovão, e chuva (são observados juntos), ou quando grandes meteoros ardentes caem por todos os lados, a recitação deve ser interrompida até a mesma hora (no dia seguinte, contando a partir da ocorrência do evento).` },
        { id: 'cm-4-104', number: 'Verso 104', text: `Quando se percebe estes (fenômenos) todos juntos (no crepúsculo), após os fogos sagrados terem sido feitos para arder (para a realização do *Agnihotra*), então se deve saber que a recitação do Veda é proibida, e também quando nuvens aparecem fora de estação.` },
        { id: 'cm-4-105', number: 'Verso 105', text: `Na (ocasião de) um som preternatural do céu, (de) um terremoto, e quando as luzes do céu estão cercadas por um halo, que ele saiba que (o estudo do Veda deve ser) parado até a mesma hora (no dia seguinte), mesmo se (esses fenômenos acontecerem) na estação (chuvosa).` },
        { id: 'cm-4-106', number: 'Verso 106', text: `Mas quando relâmpago e o rugido do trovão (são observados) após os fogos sagrados terem sido feitos para arder, a parada deverá durar enquanto a luz (do sol ou das estrelas for visível); se o restante (fenômeno acima nomeado, chuva, ocorrer, a leitura cessará), tanto de dia quanto de noite.` },
        { id: 'cm-4-107', number: 'Verso 107', text: `Para aqueles que desejam adquirir mérito sumamente grande, uma interrupção contínua do estudo do Veda (é prescrita) em vilas e cidades, e (o estudo do Veda deve) sempre (cessar) quando qualquer tipo de mau cheiro (for perceptível).` },
        { id: 'cm-4-108', number: 'Verso 108', text: `Em uma vila onde jaz um cadáver, na presença de um (homem que vive tão injustamente quanto um) *Sudra*, enquanto (o som do) choro (é ouvido), e em uma multidão de homens a (recitação do Veda deve ser) parada.` },
        { id: 'cm-4-109', number: 'Verso 109', text: `Na água, durante a parte do meio da noite, enquanto ele excrete excrementos, ou esteja impuro, e após ele ter partilhado de um jantar fúnebre, um homem não deve nem mesmo pensar em seu coração (nos textos sagrados).` },
        { id: 'cm-4-110', number: 'Verso 110', text: `Um *Brahmana* erudito não deverá recitar o Veda durante três dias, quando ele tiver aceitado um convite para um (rito fúnebre) em honra a um ancestral (*ekoddishta*), ou quando o rei tiver se tornado impuro através de um nascimento ou morte em sua família (*sutaka*), ou quando *Rahu* através de um eclipse tornar a lua impura.` },
        { id: 'cm-4-111', number: 'Verso 111', text: `Enquanto o cheiro e as manchas do (alimento dado) em honra a um ancestral permanecerem no corpo de um *Brahmana* erudito, por todo esse tempo ele não deve recitar o Veda.` },
        { id: 'cm-4-112', number: 'Verso 112', text: `Enquanto deitado em uma cama, enquanto seus pés estão erguidos (num banco), enquanto ele senta sobre seus calcanhares com um pano amarrado ao redor de seus joelhos, que ele não estude, nem quando tiver comido carne ou comida dada por uma pessoa impura em virtude de um nascimento ou morte,` },
        { id: 'cm-4-113', number: 'Verso 113', text: `Nem durante um nevoeiro, nem enquanto o som de flechas for audível, nem durante ambos os crepúsculos, nem no dia de lua nova, nem no décimo quarto e no oitavo (dias de cada quinzena), nem no dia de lua cheia.` },
        { id: 'cm-4-114', number: 'Verso 114', text: `O dia de lua nova destrói o professor, o décimo quarto (dia) o pupilo, o oitavo e os dias de lua cheia (destroem toda a lembrança do) Veda; que ele portanto evite (ler nesses) (dias).` },
        { id: 'cm-4-115', number: 'Verso 115', text: `Um *Brahmana* não recitará (o Veda) durante uma tempestade de areia, nem enquanto o céu estiver preternaturalmente vermelho, nem enquanto chacais uivarem, nem enquanto o latido de cães, o zurro de burros, ou o grunhido de camelos (for ouvido), nem enquanto (ele estiver sentado) em uma companhia.` },
        { id: 'cm-4-116', number: 'Verso 116', text: `Que ele não estude perto de um cemitério, nem perto de uma vila, nem num curral, nem vestido em uma veste que ele usou durante a relação conjugal, nem após receber um presente em um sacrifício fúnebre.` },
        { id: 'cm-4-117', number: 'Verso 117', text: `Seja um animal ou uma coisa inanimada, seja qual for o (presente) em um *Sraddha*, que ele não, tendo acabado de aceitá-lo, recite o Veda; pois a mão de um *Brahmana* é sua boca.` },
        { id: 'cm-4-118', number: 'Verso 118', text: `Quando a vila tiver sido sitiada por ladrões, e quando um alarme tiver sido soado por fogo, que ele saiba que (o estudo do Veda deve ser) interrompido até a mesma hora (no dia seguinte), e na (ocorrência de) todos os presságios.` },
        { id: 'cm-4-119', number: 'Verso 119', text: `Na (ocasião do) *Upakarman* e (do) *Vedotsarga* uma omissão (do estudo do Veda) por três dias tem sido prescrita, mas nas *Ashtakas* e nas últimas noites das estações por um dia e uma noite.` },
        { id: 'cm-4-120', number: 'Verso 120', text: `Que ele não recite o Veda a cavalo, nem numa árvore, nem num elefante, nem num barco (ou navio), nem num burro, nem num camelo, nem de pé sobre terra árida, nem viajando numa carruagem,` },
        { id: 'cm-4-121', number: 'Verso 121', text: `Nem durante uma altercação verbal, nem durante um ataque mútuo, nem num acampamento, nem durante uma batalha, nem quando ele tiver acabado de comer, nem durante uma indigestão, nem após vomitar, nem com eructações ácidas,` },
        { id: 'cm-4-122', number: 'Verso 122', text: `Nem sem receber permissão de um convidado (que fique em sua casa), nem enquanto o vento sopra veementemente, nem enquanto sangue flui de seu corpo, nem quando ele é ferido por uma arma.` },
        { id: 'cm-4-123', number: 'Verso 123', text: `Que ele nunca recite o *Rig-veda* ou o *Yagur-veda* enquanto as (melodias) *Saman* são ouvidas; (que ele pare todo estudo do Veda por um dia e uma noite) após terminar um Veda ou após recitar um *Aranyaka*.` },
        { id: 'cm-4-124', number: 'Verso 124', text: `O *Rig-veda* é declarado ser sagrado para os deuses, o *Yagur-veda* sagrado para os homens, e o *Sama-veda* sagrado para os manes; daí que o som deste último é impuro (por assim dizer).` },
        { id: 'cm-4-125', number: 'Verso 125', text: `Sabendo disto, os eruditos diariamente repetem primeiro na devida ordem a essência dos três (Vedas) e posteriormente o (texto do) Veda.` },
        { id: 'cm-4-126', number: 'Verso 126', text: `Saiba que (o estudo do Veda deve ser) interrompido por um dia e uma noite, quando gado, um sapo, um gato, um cão, uma cobra, um icnêumone, ou um rato passarem entre (o professor e seu pupilo).` },
        { id: 'cm-4-127', number: 'Verso 127', text: `Que um homem duas-vezes-nascido sempre cuidadosamente interrompa o estudo do Veda em duas (ocasiões, a saber) quando o lugar onde ele recita for impuro, e quando ele mesmo estiver não purificado.` },
        { id: 'cm-4-128', number: 'Verso 128', text: `Um homem duas-vezes-nascido que é um *Snataka* deverá permanecer casto no dia de lua nova, no oitavo (dia lunar de cada quinzena), no dia de lua cheia, e no décimo quarto, mesmo (se eles caírem) no período (adequado para a relação conjugal).` },
        { id: 'cm-4-129', number: 'Verso 129', text: `Que ele não se banhe (imediatamente) após uma refeição, nem quando ele estiver doente, nem no meio da noite, nem frequentemente vestido com todas as suas roupas, nem num espelho d'água que ele não conheça perfeitamente.` },
        { id: 'cm-4-130', number: 'Verso 130', text: `Que ele não pise intencionalmente na sombra das (imagens das) deuses, de um Guru, de um rei, de um *Snataka*, de seu professor, de um animal marrom-avermelhado, ou de alguém que tenha sido iniciado à realização de um sacrifício *Srauta* (*Dikshita*).` },
        { id: 'cm-4-131', number: 'Verso 131', text: `Ao meio-dia e à meia-noite, após partilhar de carne num jantar fúnebre, e nos dois crepúsculos, que ele não fique por muito tempo numa encruzilhada.` },
        { id: 'cm-4-132', number: 'Verso 132', text: `Que ele não pise intencionalmente em coisas usadas para a limpeza do corpo, em água usada para um banho, em urina ou excremento, em sangue, em muco, e em qualquer coisa cuspida ou vomitada.` },
        { id: 'cm-4-133', number: 'Verso 133', text: `Que ele não preste particular atenção a um inimigo, ao amigo de um inimigo, a um homem perverso, a um ladrão, ou à esposa de outro homem.` },
        { id: 'cm-4-134', number: 'Verso 134', text: `Pois neste mundo não há nada tão prejudicial à vida longa quanto a conversa criminosa com a esposa de outro homem.` },
        { id: 'cm-4-135', number: 'Verso 135', text: `Que aquele que deseja prosperidade, de fato, nunca despreze um *Kshatriya*, uma cobra, e um *Brahmana* erudito, por mais fracos que sejam.` },
        { id: 'cm-4-136', number: 'Verso 136', text: `Porque estes três, quando tratados com desrespeito, podem destruí-lo completamente; daí que um homem sábio nunca deve desprezá-los.` },
        { id: 'cm-4-137', number: 'Verso 137', text: `Que ele não despreze a si mesmo por conta de fracassos anteriores; até a morte que ele busque a fortuna, nem se desespere de ganhá-la.` },
        { id: 'cm-4-138', number: 'Verso 138', text: `Que ele diga o que é verdade, que ele diga o que é agradável, que ele não profira nenhuma verdade desagradável, e que ele não profira nenhuma falsidade agradável; essa é a lei eterna.` },
        { id: 'cm-4-139', number: 'Verso 139', text: `(O que está) bem, que ele chame de bem, ou que ele diga 'bem' apenas; que ele não se engaje em uma inimizade ou disputa inútil com ninguém.` },
        { id: 'cm-4-140', number: 'Verso 140', text: `Que ele não viaje muito cedo de manhã, nem muito tarde à noite, nem justo durante (o calor) do meio-dia, nem com um (companheiro) desconhecido, nem sozinho, nem com *Sudras*.` },
        { id: 'cm-4-141', number: 'Verso 141', text: `Que ele não insulte aqueles que têm membros redundantes ou são deficientes em membros, nem aqueles destituídos de conhecimento, nem homens muito velhos, nem aqueles que não têm beleza ou riqueza, nem aqueles que são de baixo nascimento.` },
        { id: 'cm-4-142', number: 'Verso 142', text: `Um *Brahmana* que é impuro não deve tocar com sua mão uma vaca, um *Brahmana*, ou o fogo; nem, estando em boa saúde, que ele olhe para os luminares no céu, enquanto ele for impuro.` },
        { id: 'cm-4-143', number: 'Verso 143', text: `Se ele tocou estes, enquanto impuro, que ele sempre borrife com sua mão água sobre os órgãos de sensação, todos os seus membros, e o umbigo.` },
        { id: 'cm-4-144', number: 'Verso 144', text: `Exceto quando doente, ele não deve tocar as cavidades (do corpo) sem uma razão, e ele deve evitar (tocar) o pelo nas (partes) secretas.` },
        { id: 'cm-4-145', number: 'Verso 145', text: `Que ele siga avidamente os (costumes que são) auspiciosos e a regra de boa conduta, seja cuidadoso com a pureza, e controle todos os seus órgãos, que ele murmure (orações) e, incansável, diariamente ofereça oblações no fogo.` },
        { id: 'cm-4-146', number: 'Verso 146', text: `Nenhuma calamidade acontece com aqueles que avidamente seguem os costumes auspiciosos e a regra de boa conduta, àqueles que são sempre cuidadosos com a pureza, e àqueles que murmuram (textos sagrados) e oferecem oblações queimadas.` },
        { id: 'cm-4-147', number: 'Verso 147', text: `Que ele, sem se cansar, diariamente murmure o Veda no tempo adequado; pois eles declaram que esse é o dever mais alto de alguém; (todas) outras (observâncias) são chamadas de deveres secundários.` },
        { id: 'cm-4-148', number: 'Verso 148', text: `Ao recitar diariamente o Veda, pela (observância das regras de) purificação, por (praticar) austeridades, e por não fazer nenhum ferimento a criaturas criadas, alguém (obtém a faculdade de) lembrar-se de nascimentos anteriores.` },
        { id: 'cm-4-149', number: 'Verso 149', text: `Aquele que, recordando-se de suas existências anteriores, novamente recita o Veda, ganha infindável bem-aventurança pelo contínuo estudo do Veda.` },
        { id: 'cm-4-150', number: 'Verso 150', text: `Que ele sempre ofereça nos dias-*Parva* oblações à *Savitri* e tais quais evitem maus presságios, e nas *Ashtakas* e *Anvashtakas* que ele adore constantemente os manes.` },
        { id: 'cm-4-151', number: 'Verso 151', text: `Longe de sua habitação que ele remova a urina (e o excremento), longe (que ele remova) a água usada para lavar seus pés, e longe os restos de comida e a água de seu banho.` },
        { id: 'cm-4-152', number: 'Verso 152', text: `Somente de manhã cedo que ele excrete fezes, decore (seu corpo), banhe-se, limpe seus dentes, aplique colírio aos seus olhos, e adore os deuses.` },
        { id: 'cm-4-153', number: 'Verso 153', text: `Mas nos dias-*Parva* que ele vá visitar as (imagens dos) deuses, e *Brahmanas* virtuosos, e o governante (do país), pelo bem da proteção, assim como seus *Gurus*.` },
        { id: 'cm-4-154', number: 'Verso 154', text: `Que ele saúde reverencialmente os homens veneráveis (que o visitam), dê a eles seu próprio assento, que ele se sente perto deles com as mãos unidas e, quando eles partirem, (os acompanhe), caminhando atrás deles.` },
        { id: 'cm-4-155', number: 'Verso 155', text: `Que ele, incansável, siga a conduta de homens virtuosos, conectada com suas ocupações, a qual foi integralmente declarada nos textos revelados e na tradição sagrada (*Smriti*) e é a raiz da lei sagrada.` },
        { id: 'cm-4-156', number: 'Verso 156', text: `Através da conduta virtuosa ele obtém longa vida, através da conduta virtuosa descendência desejável, através da conduta virtuosa riqueza imperecível; a conduta virtuosa destrói (o efeito de) marcas inauspiciosas.` },
        { id: 'cm-4-157', number: 'Verso 157', text: `Pois um homem de má conduta é censurado entre as pessoas, sofre infortúnios constantemente, é afligido com doenças, e tem vida curta.` },
        { id: 'cm-4-158', number: 'Verso 158', text: `Um homem que segue a conduta dos virtuosos, tem fé e é livre de inveja, vive cem anos, embora ele seja inteiramente destituído de marcas auspiciosas.` },
        { id: 'cm-4-159', number: 'Verso 159', text: `Que ele evite cuidadosamente todos os empreendimentos (cujo sucesso) dependa de outros; mas que ele busque avidamente aquilo (cuja realização) dependa de si mesmo.` },
        { id: 'cm-4-160', number: 'Verso 160', text: `Tudo que depende de outros (dá) dor, tudo que depende de si mesmo (dá) prazer; saiba que esta é a breve definição de prazer e dor.` },
        { id: 'cm-4-161', number: 'Verso 161', text: `Quando a realização de um ato alegra seu coração, que ele o realize com diligência; mas que ele evite o oposto.` },
        { id: 'cm-4-162', number: 'Verso 162', text: `Que ele nunca ofenda o professor que o iniciou, nem aquele que explicou o Veda, nem seu pai e mãe, nem (qualquer outro) *Guru*, nem vacas, nem *Brahmanas*, nem quaisquer homens realizando austeridades.` },
        { id: 'cm-4-163', number: 'Verso 163', text: `Que ele evite o ateísmo, a crítica aos Vedas, o desprezo aos deuses, o ódio, a falta de modéstia, o orgulho, a ira, e a dureza.` },
        { id: 'cm-4-164', number: 'Verso 164', text: `Que ele, quando zangado, não levante um bastão contra outro homem, nem ataque (ninguém) exceto um filho ou um pupilo; a esses dois ele pode bater a fim de corrigi-los.` },
        { id: 'cm-4-165', number: 'Verso 165', text: `Um homem duas-vezes-nascido que meramente ameaçou um *Brahmana* com a intenção de (causar a ele) um ferimento corporal, vagará por cem anos no inferno *Tamisra*.` },
        { id: 'cm-4-166', number: 'Verso 166', text: `Tendo-o golpeado intencionalmente com raiva, mesmo com uma lâmina de grama, ele nascerá durante vinte e uma existências nos úteros (de tais seres onde os homens nascem em punição por seus) pecados.` },
        { id: 'cm-4-167', number: 'Verso 167', text: `Um homem que em sua loucura fez sangue fluir do corpo de um *Brahmana* que não o ataca, sofrerá após a morte dor sumamente grande.` },
        { id: 'cm-4-168', number: 'Verso 168', text: `Tantas partículas de poeira quantas o sangue apanhar do chão, durante tantos anos o derramador do sangue será devorado por outros (animais) no outro mundo.` },
        { id: 'cm-4-169', number: 'Verso 169', text: `Um homem sábio deveria portanto nunca ameaçar um *Brahmana*, nem golpeá-lo mesmo com uma lâmina de grama, nem causar que seu sangue flua.` },
        { id: 'cm-4-170', number: 'Verso 170', text: `Nem um homem que (vive) injustamente, nem aquele que (adquire) riqueza (dizendo) falsidades, nem aquele que sempre se deleita em fazer o mal, jamais alcançam a felicidade neste mundo.` },
        { id: 'cm-4-171', number: 'Verso 171', text: `Que ele, embora sofrendo em consequência de sua retidão, nunca volte seu coração para a injustiça; pois ele verá a rápida derrubada de homens perversos e injustos.` },
        { id: 'cm-4-172', number: 'Verso 172', text: `A injustiça, praticada neste mundo, não produz seu fruto de uma vez, como uma vaca; mas, avançando lentamente, ela corta as raízes daquele que a cometeu.` },
        { id: 'cm-4-173', number: 'Verso 173', text: `Se (a punição recair) não sobre (o ofensor) mesmo, (ela recai) sobre seus filhos, se não sobre os filhos, (ao menos) sobre seus netos; mas uma iniquidade (uma vez) cometida, nunca falha em produzir fruto àquele que a forjou.` },
        { id: 'cm-4-174', number: 'Verso 174', text: `Ele prospera por um tempo através da injustiça, então ele ganha grande boa fortuna, a seguir ele conquista seus inimigos, mas (por fim) ele perece (ramo e) raiz.` },
        { id: 'cm-4-175', number: 'Verso 175', text: `Que ele sempre se deleite na veracidade, (obediência à) lei sagrada, conduta digna de um Ariano, e pureza; que ele castigue seus pupilos de acordo com a lei sagrada; que ele mantenha sua fala, seus braços, e seu ventre sob controle.` },
        { id: 'cm-4-176', number: 'Verso 176', text: `Que ele evite (a aquisição de) riqueza e (a gratificação de seus) desejos, se eles são opostos à lei sagrada, e mesmo atos lícitos que possam causar dor no futuro ou são ofensivos aos homens.` },
        { id: 'cm-4-177', number: 'Verso 177', text: `Que ele não seja inutilmente ativo com suas mãos e pés, ou com seus olhos, nem tortuoso (em seus caminhos), nem fale ociosamente, nem fira outros por atos ou mesmo pense nisso.` },
        { id: 'cm-4-178', number: 'Verso 178', text: `Que ele caminhe naquele caminho de homens santos que seus pais e seus avós seguiram; enquanto ele caminhar nele, ele não sofrerá dano.` },
        { id: 'cm-4-179', number: 'Verso 179', text: `Com um sacerdote oficiante ou doméstico, com um professor, com um tio materno, um convidado e um dependente, com crianças, idosos e doentes, com homens eruditos, com seus parentes paternos, conexões por casamento e parentes maternos,` },
        { id: 'cm-4-180', number: 'Verso 180', text: `Com seu pai e sua mãe, com parentes do sexo feminino, com um irmão, com seu filho e sua esposa, com sua filha e com seus escravos, que ele não tenha querelas.` },
        { id: 'cm-4-181', number: 'Verso 181', text: `Se ele evitar querelas com estas pessoas, ele será liberto de todos os pecados, e por suprimir (todas as) tais (querelas) um chefe de família conquista todos os mundos seguintes.` },
        { id: 'cm-4-182', number: 'Verso 182', text: `O professor é o senhor do mundo de Brahman, o pai tem poder sobre o mundo do Senhor dos seres criados (*Pragapati*), um convidado governa sobre o mundo de Indra, e os sacerdotes sobre o mundo dos deuses.` },
        { id: 'cm-4-183', number: 'Verso 183', text: `As parentes do sexo feminino (têm poder) sobre o mundo das *Apsarases*, os parentes maternos sobre o dos *Visve Devas*, as conexões por casamento sobre o das águas, a mãe e o tio materno sobre a terra.` },
        { id: 'cm-4-184', number: 'Verso 184', text: `Crianças de colo, homens idosos, pobres e doentes devem ser considerados como governantes da esfera média, o irmão mais velho como igual ao pai, a própria esposa e o próprio filho como o próprio corpo,` },
        { id: 'cm-4-185', number: 'Verso 185', text: `Os próprios escravos como a própria sombra, a própria filha como o objeto mais alto de ternura; daí que se for ofendido por (qualquer um) destes, deve suportá-lo sem ressentimento.` },
        { id: 'cm-4-186', number: 'Verso 186', text: `Embora (por seu aprendizado e santidade) ele possa ter o direito de aceitar presentes, que ele não se apegue (demasiadamente) a esse (hábito); pois através da sua aceitação (de muitos) presentes a luz divina nele é logo extinta.` },
        { id: 'cm-4-187', number: 'Verso 187', text: `Sem um conhecimento pleno das regras, prescritas pela lei sagrada para a aceitação de presentes, um homem sábio não deveria tomar nada, ainda que ele possa definhar de fome.` },
        { id: 'cm-4-188', number: 'Verso 188', text: `Mas um (homem) ignorante que aceita ouro, terra, um cavalo, uma vaca, comida, um vestido, grãos de gergelim, (ou) manteiga clarificada, é reduzido a cinzas como (um pedaço de) madeira.` },
        { id: 'cm-4-189', number: 'Verso 189', text: `O ouro e a comida destroem a sua longevidade, a terra e uma vaca o seu corpo, um cavalo o seu olho (visão), uma veste a sua pele, a manteiga clarificada a sua energia, grãos de gergelim a sua descendência.` },
        { id: 'cm-4-190', number: 'Verso 190', text: `Um *Brahmana* que não realiza austeridades nem estuda o Veda, mas se deleita em aceitar presentes, afunda com o (doador no inferno), assim como (aquele que tenta cruzar num) barco feito de pedra (é submerso) na água.` },
        { id: 'cm-4-191', number: 'Verso 191', text: `Daí que um (homem) ignorante deveria ter medo de aceitar quaisquer presentes; pois por causa de um (presente) muito pequeno mesmo um tolo afunda (no inferno) como uma vaca num pântano.` },
        { id: 'cm-4-192', number: 'Verso 192', text: `(Um homem) que conhece a lei não deveria oferecer nem mesmo água a um *Brahmana* que age como um gato, nem a um *Brahmana* que age como uma garça, nem a um que não está familiarizado com o Veda.` },
        { id: 'cm-4-193', number: 'Verso 193', text: `Pois a propriedade, embora ganha de acordo com regras prescritas, que é dada a estas três (pessoas), causa no outro mundo miséria tanto ao doador quanto ao recebedor.` },
        { id: 'cm-4-194', number: 'Verso 194', text: `Assim como aquele que (tenta) cruzar a água num barco de pedra afunda (até o fundo), assim também um doador ignorante e um donatário ignorante afundam baixo.` },
        { id: 'cm-4-195', number: 'Verso 195', text: `(Um homem) que, sempre cobiçoso, exibe a bandeira da virtude, (que é) um hipócrita, um enganador do povo, intencionado a causar dano, (e) um detrator (dos méritos) de todos os homens, deve-se saber ser aquele que age como um gato.` },
        { id: 'cm-4-196', number: 'Verso 196', text: `Aquele *Brahmana*, que com o olhar cabisbaixo, de uma disposição cruel, está unicamente focado em atingir seus próprios fins, desonesto e falsamente gentil, é um que age como uma garça.` },
        { id: 'cm-4-197', number: 'Verso 197', text: `Aqueles *Brahmanas* que agem como garças, e aqueles que exibem as características de gatos, caem em consequência desse perverso modo de agir no (inferno chamado) *Andhatamisra*.` },
        { id: 'cm-4-198', number: 'Verso 198', text: `Quando ele tiver cometido um pecado, que ele não realize uma penitência sob o pretexto (de que o ato é intencionado a ganhar) mérito espiritual, (assim) escondendo o seu pecado sob (o pretexto de) um voto e enganando as mulheres e os *Sudras*.` },
        { id: 'cm-4-199', number: 'Verso 199', text: `Tais *Brahmanas* são repreendidos após a morte e nesta (vida) por aqueles que expõem o Veda, e um voto, realizado sob um falso pretexto, vai para os *Rakshasas*.` },
        { id: 'cm-4-200', number: 'Verso 200', text: `Aquele que, sem ser um estudante, ganha a sua subsistência por (usar) a veste de um estudante, toma sobre si a culpa de (todos os) estudantes e nasce de novo no útero de um animal.` },
        { id: 'cm-4-201', number: 'Verso 201', text: `Que ele nunca se banhe em tanques pertencentes a outros homens; se ele se banha (em um desses), ele é maculado por uma porção da culpa daquele que fez o tanque.` },
        { id: 'cm-4-202', number: 'Verso 202', text: `Aquele que usa sem permissão uma carruagem, uma cama, um assento, um poço, um jardim ou uma casa pertencente a um (outro homem), toma sobre si um quarto da culpa (do proprietário).` },
        { id: 'cm-4-203', number: 'Verso 203', text: `Que ele sempre se banhe em rios, em lagoas, cavadas pelos deuses (eles mesmos), em lagos, e em poços de água ou nascentes.` },
        { id: 'cm-4-204', number: 'Verso 204', text: `Um homem sábio deveria cumprir constantemente os deveres primordiais (chamados *yama*), mas não sempre os menores (chamados *niyama*); pois aquele que não cumpre os primeiros, enquanto obedece apenas aos últimos, torna-se um pária.` },
        { id: 'cm-4-205', number: 'Verso 205', text: `Um *Brahmana* nunca deve comer (um jantar dado) em um sacrifício que é oferecido por um que não é um *Srotriya*, por um que sacrifica para uma multidão de homens, por uma mulher, ou por um eunuco.` },
        { id: 'cm-4-206', number: 'Verso 206', text: `Quando essas pessoas oferecem iguarias sacrificiais no fogo, é azar para os (homens) santos e desagrada os deuses; que ele portanto o evite.` },
        { id: 'cm-4-207', number: 'Verso 207', text: `Que ele nunca coma (comida dada) por (homens) intoxicados, zangados, ou doentes, nem aquela na qual cabelos ou insetos são encontrados, nem o que foi tocado intencionalmente com o pé,` },
        { id: 'cm-4-208', number: 'Verso 208', text: `Nem aquela para a qual o assassino de um *Brahmana* erudito olhou, nem aquela que foi tocada por uma mulher menstruada, nem aquela que foi bicada por pássaros ou tocada por um cão,` },
        { id: 'cm-4-209', number: 'Verso 209', text: `Nem comida na qual uma vaca cheirou, nem particularmente aquela que foi oferecida por um convite a todos os que chegarem, nem aquela (dada) por uma multidão ou por prostitutas, nem aquela que é declarada ser má por um (homem) erudito,` },
        { id: 'cm-4-210', number: 'Verso 210', text: `Nem a comida (dada) por um ladrão, um músico, um carpinteiro, um usurário, um que foi iniciado (para a realização de um sacrifício *Srauta*), um avarento, um atado com grilhões,` },
        { id: 'cm-4-211', number: 'Verso 211', text: `Por um acusado de um pecado mortal (*Abhisasta*), um hermafrodita, uma mulher impudica, ou um hipócrita, nem (qualquer coisa doce) que azedou, nem o que foi mantido por uma noite inteira, nem (a comida) de um *Sudra*, nem as sobras (de outro homem),` },
        { id: 'cm-4-212', number: 'Verso 212', text: `Nem (a comida dada) por um médico, um caçador, um homem cruel, um que come os fragmentos (da refeição de outro), nem a comida de um *Ugra*, nem aquela preparada para uma mulher no puerpério, nem aquela (dada num jantar) onde (um convidado se levanta) prematuramente (e) sorve água, nem aquela (dada por uma mulher) cujos dez dias de impureza não se passaram,` },
        { id: 'cm-4-213', number: 'Verso 213', text: `Nem (comida) dada sem o devido respeito, nem (aquela que contém) carne comida por nenhum propósito sagrado, nem (aquela dada) por uma fêmea que não tem (parentes) do sexo masculino, nem a comida de um inimigo, nem aquela (dada) pelo senhor de uma cidade, nem aquela (dada) por párias, nem aquela sobre a qual qualquer um tenha espirrado;` },
        { id: 'cm-4-214', number: 'Verso 214', text: `Nem a comida (dada) por um informante, por aquele que habitualmente diz falsidades, ou por aquele que vende (as recompensas de) sacrifícios, nem a comida (dada) por um ator, um alfaiate, ou um (homem) ingrato,` },
        { id: 'cm-4-215', number: 'Verso 215', text: `Por um ferreiro, um *Nishada*, um ator de palco, um ourives, um cesteiro, ou um negociante de armas,` },
        { id: 'cm-4-216', number: 'Verso 216', text: `Por treinadores de cães de caça, taberneiros, um lavadeiro, um tintureiro, um (homem) impiedoso, e um homem em cuja casa (vive) um amante (de sua esposa),` },
        { id: 'cm-4-217', number: 'Verso 217', text: `Nem (a comida dada) por aqueles que conscientemente toleram os amantes (de suas esposas), e por aqueles que em todos os assuntos são governados por mulheres, nem a comida (dada por homens) cujos dez dias de impureza por conta de uma morte não se passaram, nem aquela que é intragável.` },
        { id: 'cm-4-218', number: 'Verso 218', text: `A comida de um rei prejudica o seu vigor, a comida de um *Sudra* a sua excelência no aprendizado sagrado, a comida de um ourives a sua longevidade, a de um cortador de couro a sua fama;` },
        { id: 'cm-4-219', number: 'Verso 219', text: `A comida de um artesão destrói a sua descendência, a de um lavadeiro a sua força (corporal); a comida de uma multidão e de prostitutas o exclui dos mundos (mais altos).` },
        { id: 'cm-4-220', number: 'Verso 220', text: `A comida de um médico (é tão vil quanto) pus, a de uma mulher impudica (igual a) sêmen, a de um usurário (tão vil quanto) excremento, e a de um negociante de armas (tão má quanto) sujeira.` },
        { id: 'cm-4-221', number: 'Verso 221', text: `A comida daquelas outras pessoas que foram enumeradas sucessivamente como tais cuja comida não deve ser comida, os sábios declaram (ser tão impura quanto) pele, ossos, e cabelo.` },
        { id: 'cm-4-222', number: 'Verso 222', text: `Se ele ingeriu inadvertidamente a comida de um desses, (ele deve) jejuar por três dias; se ele a ingeriu intencionalmente, ou (engoliu) sêmen, excremento, ou urina, ele deve realizar uma penitência *Krikkhra*.` },
        { id: 'cm-4-223', number: 'Verso 223', text: `Um *Brahmana* que conhece (a lei) não deve comer comida cozida (dada) por um *Sudra* que não realiza *Sraddhas*; mas, na falta de (outros) meios de subsistência, ele pode aceitar (grão) cru, suficiente para uma noite (e dia).` },
        { id: 'cm-4-224', number: 'Verso 224', text: `Os deuses, tendo considerado (os respectivos méritos) de um *Srotriya* avaro e de um usurário liberal, declararam a comida de ambos como sendo igual (em qualidade).` },
        { id: 'cm-4-225', number: 'Verso 225', text: `O Senhor dos seres criados (*Pragapati*) veio e lhes disse, 'Não torneis igual o que é desigual. A comida desse (usurário) liberal é purificada pela fé; (a do) (do) outro (homem) é profanada por uma falta de fé.'` },
        { id: 'cm-4-226', number: 'Verso 226', text: `Que ele, sem cansar-se, sempre ofereça sacrifícios e realize obras de caridade com fé; pois oferendas e obras de caridade feitas com fé e com dinheiro ganho licitamente, (proporcionam) recompensas infinitas.` },
        { id: 'cm-4-227', number: 'Verso 227', text: `Que ele sempre pratique, de acordo com a sua capacidade, com um coração alegre, o dever da liberalidade, tanto por sacrifícios quanto por obras de caridade, se ele encontrar um recipiente digno (para os seus presentes).` },
        { id: 'cm-4-228', number: 'Verso 228', text: `Se lhe for pedido, que ele sempre dê algo, por menos que seja, sem ressentimento; pois um recipiente digno (talvez) será encontrado que o salve de toda (a culpa).` },
        { id: 'cm-4-229', number: 'Verso 229', text: `Um doador de água obtém a satisfação (de sua fome e sede), um doador de comida a felicidade imperecível, um doador de gergelim descendência desejável, um doador de uma lâmpada uma visão muito excelente.` },
        { id: 'cm-4-230', number: 'Verso 230', text: `Um doador de terra obtém terra, um doador de ouro longa vida, um doador de uma casa mansões muito excelentes, um doador de prata (*rupya*) beleza requintada (*rupa*),` },
        { id: 'cm-4-231', number: 'Verso 231', text: `Um doador de uma veste um lugar no mundo da lua, um doador de um cavalo (*asva*) um lugar no mundo dos *Asvins*, um doador de um boi de tração grande boa fortuna, um doador de uma vaca o mundo do sol;` },
        { id: 'cm-4-232', number: 'Verso 232', text: `Um doador de uma carruagem ou de uma cama uma esposa, um doador de proteção domínio supremo, um doador de grãos bem-aventurança eterna, um doador do Veda (*brahman*) união com Brahman;` },
        { id: 'cm-4-233', number: 'Verso 233', text: `O dom do Veda supera todos os outros presentes, água, comida, vacas, terra, roupas, gergelim, ouro, e manteiga clarificada.` },
        { id: 'cm-4-234', number: 'Verso 234', text: `Para qualquer propósito (que um homem) conceda qualquer presente, para esse mesmo propósito ele recebe (em seu próximo nascimento) com a devida honra a sua (recompensa).` },
        { id: 'cm-4-235', number: 'Verso 235', text: `Tanto aquele que respeitosamente recebe (um presente), quanto aquele que respeitosamente o concede, vão para o céu; no caso contrário (ambos caem) no inferno.` },
        { id: 'cm-4-236', number: 'Verso 236', text: `Que ele não se orgulhe de suas austeridades; que ele não profira uma falsidade após ter oferecido um sacrifício; que ele não fale mal dos *Brahmanas*, embora seja atormentado (por eles); quando tiver concedido (um presente), que não se gabe dele.` },
        { id: 'cm-4-237', number: 'Verso 237', text: `Pela falsidade um sacrifício torna-se em vão, pela autocomplacência (a recompensa por) austeridades é perdida, a longevidade por falar mal de *Brahmanas*, e (a recompensa de) um presente por se gabar.` },
        { id: 'cm-4-238', number: 'Verso 238', text: `Não causando dor a nenhuma criatura, que ele lentamente acumule mérito espiritual, em prol (de adquirir) um companheiro para o outro mundo, assim como a formiga branca (gradualmente levanta a sua) colina.` },
        { id: 'cm-4-239', number: 'Verso 239', text: `Pois no outro mundo nem pai, nem mãe, nem esposa, nem filhos, nem parentes ficam para serem seus companheiros; somente o mérito espiritual permanece (com ele).` },
        { id: 'cm-4-240', number: 'Verso 240', text: `Sozinho nasce cada ser; sozinho ele morre; sozinho ele goza (a recompensa de sua) virtude; sozinho (ele sofre a punição de seu) pecado.` },
        { id: 'cm-4-241', number: 'Verso 241', text: `Deixando o corpo morto no chão como um tronco de madeira, ou um torrão de terra, os parentes partem com os rostos desviados; mas o mérito espiritual segue a (alma).` },
        { id: 'cm-4-242', number: 'Verso 242', text: `Que ele portanto sempre acumule lentamente o mérito espiritual, a fim de (que ele possa ser seu) companheiro (após a morte); pois com o mérito como seu companheiro ele atravessará uma escuridão difícil de atravessar.` },
        { id: 'cm-4-243', number: 'Verso 243', text: `(Esse companheiro) rapidamente conduz o homem que é devotado ao dever e apaga os seus pecados por austeridades, ao outro mundo, radiante e vestido com um corpo etéreo.` },
        { id: 'cm-4-244', number: 'Verso 244', text: `Que ele, que deseja elevar a sua raça, forme sempre conexões com (os homens) mais excelentes, e evite todos os baixos.` },
        { id: 'cm-4-245', number: 'Verso 245', text: `Um *Brahmana* que sempre se conecta com os (homens) mais excelentes, e evita todos os inferiores, (ele mesmo) se torna mais distinto; por uma conduta oposta ele se torna um *Sudra*.` },
        { id: 'cm-4-246', number: 'Verso 246', text: `Aquele que é perseverante, gentil, (e) paciente, evita a companhia de homens de conduta cruel, e não causa dano (a criaturas vivas), ganha, se ele constantemente viver dessa maneira, controlando seus órgãos e por liberalidade, a bem-aventurança celestial.` },
        { id: 'cm-4-247', number: 'Verso 247', text: `Ele pode aceitar de qualquer (homem), combustível, água, raízes, fruta, comida oferecida sem pedir, e mel, igualmente um presente (que consiste em) uma promessa de proteção.` },
        { id: 'cm-4-248', number: 'Verso 248', text: `O Senhor dos seres criados (*Pragapati*) declarou que esmolas oferecidas livremente e trazidas (pelo próprio doador) podem ser aceitas mesmo de um homem pecador, contanto que (o presente) não tivesse sido (pedido ou) prometido de antemão.` },
        { id: 'cm-4-249', number: 'Verso 249', text: `Durante quinze anos os manes não comem (a comida) daquele homem que desdenha um (presente livremente oferecido), nem o fogo carrega suas oferendas (aos deuses).` },
        { id: 'cm-4-250', number: 'Verso 250', text: `Um sofá, uma casa, grama *Kusa*, perfumes, água, flores, joias, leite azedo, grãos, peixe, leite doce, carne, e vegetais que ele não rejeite, (se eles forem oferecidos voluntariamente.)` },
        { id: 'cm-4-251', number: 'Verso 251', text: `Aquele que deseja aliviar seus *Gurus* e aqueles a quem ele é obrigado a sustentar, ou deseja honrar aos deuses e convidados, pode aceitar (presentes) de qualquer pessoa; mas ele não deve satisfazer a sua (própria fome) com tais (presentes).` },
        { id: 'cm-4-252', number: 'Verso 252', text: `Mas se os seus *Gurus* estão mortos, ou se ele vive separado deles em (outra) casa, que ele, quando busca uma subsistência, aceite (presentes) de homens bons apenas.` },
        { id: 'cm-4-253', number: 'Verso 253', text: `Seu trabalhador no arado, um amigo de sua família, seu vaqueiro, seu escravo, e seu barbeiro são, entre os *Sudras*, aqueles cuja comida ele pode comer, igualmente (um homem pobre) que se oferece (para ser seu escravo).` },
        { id: 'cm-4-254', number: 'Verso 254', text: `Conforme é o seu caráter, conforme é o trabalho que ele deseja realizar, e conforme a maneira na qual ele tenciona servir, assim mesmo (um escravo voluntário) deve oferecer-se.` },
        { id: 'cm-4-255', number: 'Verso 255', text: `Aquele que descreve a si mesmo aos (homens) virtuosos, de uma maneira contrária à verdade, é o (miserável) mais pecador neste mundo; ele é um ladrão que foge com o seu próprio eu.` },
        { id: 'cm-4-256', number: 'Verso 256', text: `Todas as coisas (têm a sua natureza) determinada pela fala; a fala é a sua raiz, e da fala elas procedem; mas aquele que é desonesto com relação à fala, é desonesto em tudo.` },
        { id: 'cm-4-257', number: 'Verso 257', text: `Quando ele tiver pago, de acordo com a lei, suas dívidas com os grandes sábios, com os manes, e com os deuses, que ele transfira tudo para o seu filho e habite (em sua casa), não se importando com quaisquer preocupações mundanas.` },
        { id: 'cm-4-258', number: 'Verso 258', text: `Sozinho que ele constantemente medite em solidão sobre aquilo que é salutar para a sua alma; pois aquele que medita em solidão alcança a suprema bem-aventurança.` },
        { id: 'cm-4-259', number: 'Verso 259', text: `Assim foram declarados os meios pelos quais um chefe de família *Brahmana* deve sempre subsistir, e o sumário das ordenanças para um *Snataka*, que causam um aumento de santidade e são louváveis.` },
        { id: 'cm-4-260', number: 'Verso 260', text: `Um *Brahmana* que, sendo erudito no conhecimento dos Vedas, conduz a si mesmo desta maneira e diariamente destrói os seus pecados, será exaltado no mundo de Brahman.` },
      ],
    },
  ],
};
